package local.villagers.capability;

import java.util.Set;

/** Immutable permissions: specific food operations are separate exceptions to terrain editing. */
public final class CapabilityPermissions {
    public enum Capability { OPEN_DOOR, CLOSE_DOOR, CONSUME_FOOD, EQUIP_ITEM, DEFENSIVE_MELEE, HARVEST_REPLANT, CRAFT_BREAD, GATHER_HAY, GATHER_PLANTING_SEEDS, CULTIVATE_NATIVE_CAMP, UNPACK_HAY, CULTIVATE_PLANT, CULTIVATE_NATIVE_VILLAGE, CRAFT_WOODEN_HOE, CRAFT_WOODEN_PICKAXE, CRAFT_STONE_PICKAXE, CRAFT_IRON_PICKAXE, CRAFT_DIAMOND_PICKAXE, CRAFT_IRON_ARMOR, MINE_SURFACE_STONE, DIG_FOOD_PASSAGE, DIG_ADVENTURE_QUARRY, BUILD_CRAFTING_TABLE, FORESTRY, SOIL_TRANSFER, CRAFT_BOAT, PILOT_BOAT, OPEN_CAMP_STORAGE, CRAFT_BED, PLACE_CAMP_BED, RELOCATE_CAMP_BED, REPAIR_QUARRY_ACCESS, OPEN_CAMP_PASSAGE, OPEN_NATIVE_FOOD_STORAGE, ESCAPE_NATIVE_CELL, DELIVER_CAMP_MEAL, DROP_SURPLUS_MATERIALS, BUILD_FORESTRY_STEP, MINE_ADVENTURE_PASSAGE, CRAFT_FURNACE, OPERATE_FURNACE, OPEN_CAMP_FOOD_HATCH, OPEN_VILLAGE_SUPPLIES, PLACE_VILLAGE_BED, OPEN_FENCE_GATE, CLOSE_FENCE_GATE, CLEAR_PREPARATION_CANOPY, CRAFT_SHEARS, SHEAR_NATIVE_SHEEP, BREAK_BLOCK, PLACE_BLOCK }
    private static final CapabilityPermissions ADVENTURE = new CapabilityPermissions(Set.of(
        Capability.OPEN_DOOR, Capability.CLOSE_DOOR, Capability.CONSUME_FOOD,
        Capability.EQUIP_ITEM, Capability.DEFENSIVE_MELEE, Capability.HARVEST_REPLANT, Capability.CRAFT_BREAD,
        Capability.GATHER_HAY, Capability.GATHER_PLANTING_SEEDS, Capability.CULTIVATE_NATIVE_CAMP, Capability.UNPACK_HAY, Capability.CULTIVATE_PLANT, Capability.CULTIVATE_NATIVE_VILLAGE, Capability.CRAFT_WOODEN_HOE, Capability.CRAFT_WOODEN_PICKAXE, Capability.CRAFT_STONE_PICKAXE, Capability.CRAFT_IRON_PICKAXE, Capability.CRAFT_DIAMOND_PICKAXE, Capability.CRAFT_IRON_ARMOR, Capability.MINE_SURFACE_STONE, Capability.DIG_FOOD_PASSAGE, Capability.DIG_ADVENTURE_QUARRY, Capability.BUILD_CRAFTING_TABLE, Capability.FORESTRY, Capability.SOIL_TRANSFER, Capability.CRAFT_BOAT, Capability.PILOT_BOAT,
        Capability.OPEN_CAMP_STORAGE,Capability.CRAFT_BED,Capability.PLACE_CAMP_BED,Capability.RELOCATE_CAMP_BED,Capability.OPEN_NATIVE_FOOD_STORAGE,Capability.ESCAPE_NATIVE_CELL,Capability.REPAIR_QUARRY_ACCESS,Capability.OPEN_CAMP_PASSAGE,Capability.DELIVER_CAMP_MEAL,Capability.DROP_SURPLUS_MATERIALS,Capability.BUILD_FORESTRY_STEP,Capability.MINE_ADVENTURE_PASSAGE,Capability.CRAFT_FURNACE,Capability.OPERATE_FURNACE,Capability.OPEN_CAMP_FOOD_HATCH,Capability.OPEN_VILLAGE_SUPPLIES,Capability.PLACE_VILLAGE_BED,Capability.OPEN_FENCE_GATE,Capability.CLOSE_FENCE_GATE,Capability.CLEAR_PREPARATION_CANOPY,Capability.CRAFT_SHEARS,Capability.SHEAR_NATIVE_SHEEP));
    private final Set<Capability> allowed;

    private CapabilityPermissions(Set<Capability> allowed) { this.allowed = Set.copyOf(allowed); }
    public static CapabilityPermissions adventure() { return ADVENTURE; }
    public boolean allows(Capability capability) { return allowed.contains(capability); }
    public Set<Capability> allowed() { return allowed; }
}
